def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    guy_patches = image_patch.find("guy")
    hand_patches = image_patch.find("hand")

    if not guy_patches or not hand_patches:
        return image_patch

    guy = guy_patches[0]
    hands = sorted(hand_patches, key=lambda h: abs(h.horizontal_center - guy.horizontal_center))

    for hand in hands:
        if hand.overlaps_with(guy.left, guy.lower, guy.right, guy.upper):
            continue

        guy_hand_distance = abs(hand.horizontal_center - guy.horizontal_center)
        other_hands = [h for h in hands if h != hand and abs(h.horizontal_center - guy.horizontal_center) < guy_hand_distance]

        if not other_hands:
            return hand

    return guy

